Para crear un diálogo que se pueda usar tanto para crear como para editar un usuario, necesitamos ajustar el componente `CreateEditUserDialogComponent` para que acepte un usuario como entrada y maneje tanto la creación como la edición. También necesitamos ajustar el componente padre `AdmUserComponent` para manejar la lógica de creación y edición de usuarios.

Aquí está el código ajustado:

### `create-edit-user-dialog.component.ts`
```ts
import { ChangeDetectionStrategy, Component, Input, Output, EventEmitter } from "@angular/core";
import { ButtonModule } from "primeng/button";
import { DialogModule } from "primeng/dialog";
import { InputTextModule } from "primeng/inputtext";

@Component({
  selector: "app-create-edit-user-dialog",
  standalone: true,
  imports: [DialogModule, ButtonModule, InputTextModule],
  templateUrl: "./create-edit-user-dialog.component.html",
  styleUrls: ["./create-edit-user-dialog.component.css"],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CreateEditUserDialogComponent {
  @Input() visible = false;
  @Input() user: any = {};
  @Output() onSave = new EventEmitter<any>();
  @Output() onCancel = new EventEmitter<void>();

  showDialog() {
    this.visible = true;
  }

  hideDialog() {
    this.visible = false;
    this.onCancel.emit();
  }

  saveUser() {
    this.onSave.emit(this.user);
    this.hideDialog();
  }
}
```

