### `adm-user.component.ts`
```ts
import {
  ChangeDetectionStrategy,
  Component,
  inject,
  signal,
  ViewChild,
} from "@angular/core";

import { TableModule } from "primeng/table";
import { ButtonModule } from "primeng/button";
import { TagModule } from "primeng/tag";

import { userStore, User } from "@store/userStore";
import { OptimisticService } from "@shared/services/optimistic.service";
import { UserTableListComponent } from "@app/administration/components/adm-user/user-table-list/user-table-list.component";
import { CreateEditUserDialogComponent } from "@app/administration/components/adm-user/create-edit-user-dialog/create-edit-user-dialog.component";

const primengModules = [ButtonModule, TableModule, TagModule];

@Component({
  selector: "app-adm-user",
  standalone: true,
  imports: [
    ...primengModules,
    UserTableListComponent,
    CreateEditUserDialogComponent,
  ],
  templateUrl: "./adm-user.component.html",
  styleUrls: ["./adm-user.component.css"],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AdmUserComponent {
  public readonly userStore = inject(userStore);
  public readonly loadingErrorService = inject(OptimisticService);

  @ViewChild(CreateEditUserDialogComponent) ceud!: CreateEditUserDialogComponent;

  createEditUserDialogVisible = signal(false);
  selectedUser: User | null = null;

  addUser() {
    this.selectedUser = { id: 0, username: '', email: '', firstName: '', lastName: '', createdAt: '' };
    this.ceud.showDialog();
  }

  editUser(user: User) {
    this.selectedUser = { ...user };
    this.ceud.showDialog();
  }

  saveUser(user: User) {
    if (user.id === 0) {
      // Create new user
      this.userStore.addUser(user);
    } else {
      // Update existing user
      this.userStore.updateUser(user);
    }
  }

  deleteUser(userId: number) {
    this.userStore.removeUser(userId);
  }

  getSeverity(status: string) {
    switch (status) {
      case "INSTOCK":
        return "success";
      case "LOWSTOCK":
        return "warning";
      case "OUTOFSTOCK":
        return "danger";
      default:
        return "unknown";
    }
  }
}
